// One runtime for editor testing and standalone export. No network dependencies.
export function mountGame(root, p, options={}){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palettes={forest:['#edf2df','#8cab6e','#335c44'],ocean:['#d7f1ef','#64b7bc','#22596c'],castle:['#ede5f4','#a493b7','#514269'],space:['#202c4c','#525b91','#c8d0f6'],lab:['#efe7dc','#ad9e84','#635c4e']};let c=palettes[p.theme]||palettes.forest;
const hero={forest:'🦊',ocean:'🐢',castle:'🧙',space:'🚀',lab:'🕵️'}[p.theme];
let state={index:0,score:0,mistakes:0,lives:p.lives,done:[],started:false,ended:false,letters:[],selected:[],feedback:'',busy:false,time:p.timer};let startedAt=0,interval=null,disposed=false;
root.style.setProperty('--sky',c[0]);root.style.setProperty('--land',c[1]);root.style.setProperty('--deep',c[2]);root.style.setProperty('--game-accent',p.accent);root.style.fontFamily=`"${p.font}",Arial,sans-serif`;root.classList.toggle('reduce-motion',!!p.reduceMotion);
const landscape=()=>`<svg class="landscape" viewBox="0 0 1200 675" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${c[0]}"/><stop offset="1" stop-color="#faf7dc"/></linearGradient><linearGradient id="hill" x2="0" y2="1"><stop stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient></defs><rect width="1200" height="675" fill="url(#sky)"/><circle cx="968" cy="126" r="63" fill="#fff6c8" opacity=".8"/><path d="M0 395Q180 260 390 387T820 360T1200 324V675H0" fill="${c[1]}" opacity=".23"/><path d="M0 495Q240 340 510 449T1200 409V675H0" fill="${c[1]}" opacity=".48"/><path d="M0 545Q240 463 520 522T1200 476V675H0" fill="url(#hill)"/><path d="M520 675Q720 550 580 475" fill="none" stroke="#e4d7a2" stroke-width="67" opacity=".5"/>${p.theme==='forest'?`<g fill="#416d4b"><path d="M-45 540L65 115L174 540Z"/><path d="M48 555L156 208L263 555Z"/><path d="M1014 520L1116 116L1240 520Z"/></g><g fill="#638454"><path d="M-55 376L65 75L185 376Z"/><path d="M1040 340L1120 77L1208 340Z"/></g><g fill="#dce8b6" opacity=".7"><circle cx="330" cy="139" r="3"/><circle cx="860" cy="265" r="4"/><circle cx="202" cy="270" r="3"/></g>`:''}${p.theme==='space'?'<g fill="#fff" opacity=".8"><circle cx="120" cy="100" r="3"/><circle cx="780" cy="74" r="4"/><circle cx="1040" cy="280" r="3"/><circle cx="280" cy="230" r="2"/><circle cx="530" cy="160" r="3"/></g>':''}</svg>`;
function objectMarkup(o,i){const asset=p.assets.find(a=>a.id===o.assetId);return `<button class="world-object ${options.edit?'editable':''} ${state.done.includes(o.wordId)?'bloomed':''}" data-object="${esc(o.id)}" data-word="${esc(o.wordId)}" aria-label="${esc(asset?.name||'Игровой объект '+(i+1))}" style="left:${o.x}%;top:${o.y}%;font-size:${o.size/12}cqw;width:${o.size/12}cqw;height:${o.size/10}cqw;opacity:${o.opacity};z-index:${o.layer};transform:translate(-50%,-50%) rotate(${o.rotation||0}deg)">${asset?`<img draggable="false" src="${esc(asset.data)}" alt="${esc(asset.name)}">`:esc(o.emoji||'🌼')}${options.edit?'<span data-resize="true" class="resize-handle" aria-hidden="true"></span>':''}</button>`;}
function shell(content){root.innerHTML=`${p.background?`<img class="landscape" src="${esc(p.background)}" alt="">`:landscape()}<div class="scene-vignette"></div><div class="scene-top"><span class="scene-pill">${p.theme==='space'?'✦ МИССИЯ':'✿ СЛОВАРНОЕ ПРИКЛЮЧЕНИЕ'}</span><div class="scene-hud"><span>${p.lives?'♥ '+state.lives:'♡ ∞'}</span><span>✦ ${state.score}</span>${p.timer?`<span>◷ ${state.time}</span>`:''}<button class="sound-toggle" title="Звук" aria-label="Переключить звук">${p.sound?'♪':'♩'}</button></div></div>${content}<div class="scene-hero">${hero}</div><div class="scene-progress">${p.words.map(w=>`<i class="${state.done.includes(w.id)?'done':''}"></i>`).join('')}</div>`;root.querySelector('.sound-toggle')?.addEventListener('click',()=>{p.sound=!p.sound;root.querySelector('.sound-toggle').textContent=p.sound?'♪':'♩';});}
function intro(){shell(`<div class="scene-heading"><div class="scene-eyebrow">${options.edit?'ВАШ МАЛЕНЬКИЙ МИР БОЛЬШИХ ОТКРЫТИЙ':'ГОТОВЫ К ПРИКЛЮЧЕНИЮ?'}</div><h2 style="font-size:${p.fontSize/7.5}cqw">${esc(p.titleText)}</h2><p>${esc(p.instruction)}</p>${!options.edit?'<button class="game-start">Начать приключение <span>→</span></button>':''}</div><div class="world-objects">${p.objects.slice((options.page||0)*12,(options.page||0)*12+12).map(objectMarkup).join('')}</div><div class="scene-sign">${p.words.length} слов · ${Math.ceil(p.words.length/6)} ${Math.ceil(p.words.length/6)===1?'раунд':'раунда'}</div>`);if(!options.edit)root.querySelector('.game-start').onclick=start;}
function start(){if(!p.words.length)return;state.started=true;startedAt=Date.now();if(p.timer)interval=setInterval(()=>{if(disposed||state.ended)return;state.time--;let t=root.querySelector('.scene-hud span:nth-child(3)');if(t)t.textContent='◷ '+state.time;if(state.time<=0)finish(false);},1000);round();}
function choices(w){return [w.word,w.wrong].sort(()=>Math.random()-.5).map(s=>`<button class="game-answer" data-answer="${esc(s)}">${esc(s)}</button>`).join('');}
function round(){if(state.index>=p.words.length)return finish(true);let w=p.words[state.index];state.busy=false;state.feedback='';let task='';let question=p.question;
if(p.game==='safe'){state.safeSolved=0;state.safePositions=safePositions(w.word);question='Запомни секретное слово';task=`<div class="safe-cabinet"><div class="safe-emblem">⌑</div><div class="safe-memory-word">${esc(w.word)}</div><p class="safe-instruction">Без спешки. Запомни написание и закрой подсказку.</p></div><button class="game-start safe-ready">Запомнил — открыть замки →</button>`;}
else if(p.game==='letters'){state.letters=Array.from(w.word).map((s,i)=>({s,i})).sort(()=>Math.random()-.5);state.selected=[];question='Собери слово по буквам';task=`<div class="letter-result" aria-live="polite">${Array.from(w.word).map(()=>'<span>·</span>').join('')}</div><div class="letter-bank">${state.letters.map((l,i)=>`<button data-letter="${i}">${esc(l.s)}</button>`).join('')}</div><button class="letter-reset">Начать слово заново</button>`;}
else if(p.game==='detective'||p.game==='sprint'){question=p.game==='detective'?'Найди и исправь ошибку':'Напиши слово правильно';task=`<div class="wrong-word">${esc(w.wrong)}</div><form class="answer-form"><input aria-label="Правильное написание" autocomplete="off" placeholder="Ваш ответ…" required><button class="game-submit">Проверить →</button></form>`;}
else if(p.game==='maze'){question='Через какие ворота пойдём?';task=`<div class="maze-path">${Array.from({length:5},(_,i)=>`<span class="${i<=state.index%5?'passed':''}">⌘</span>`).join('<b>···</b>')}</div><div class="game-answers gates">${choices(w)}</div>`;}
else{task=`<div class="game-answers ${p.game==='catch'?'floating-answers':''}">${choices(w)}</div>`;if(p.game==='space')task=`<div class="mission-orbit">🪐 <span>···········</span> 🚀</div>`+task;}
shell(`${p.game==='garden'?`<div class="game-garden">${p.objects.slice(Math.floor(state.index/12)*12,Math.floor(state.index/12)*12+12).map(objectMarkup).join('')}</div>`:''}<div class="question-panel"><div class="question-step">${p.game==='space'?'МИССИЯ':'ЗАДАНИЕ'} ${state.index+1} ИЗ ${p.words.length}</div><h3>${esc(question)}</h3>${w.hint?`<p class="word-hint">Подсказка: ${esc(w.hint)}</p>`:''}${task}<div class="answer-feedback" aria-live="polite"></div></div>`);wire(w);}
function wire(w){if(p.game==='safe')root.querySelector('.safe-ready').onclick=()=>safeLock(w);root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.answer,w));root.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();answer(e.target.querySelector('input').value,w);});root.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{if(state.busy||b.disabled)return;state.selected.push(+b.dataset.letter);b.disabled=true;root.querySelector('.letter-result').innerHTML=state.selected.map(i=>`<span>${esc(state.letters[i].s)}</span>`).join('');if(state.selected.length===Array.from(w.word).length)answer(state.selected.map(i=>state.letters[i].s).join(''),w);});root.querySelector('.letter-reset')?.addEventListener('click',round);}
function safePositions(word){
 const chars=Array.from(word);let positions=chars.map((letter,i)=>/[аоуыэяёюиеaeiou]/i.test(letter)?i:-1).filter(i=>i>=0);
 if(!positions.length)positions=chars.map((letter,i)=>/[a-zа-яё]/i.test(letter)?i:-1).filter(i=>i>=0);
 if(!positions.length)positions=chars.map((_,i)=>i);
 return positions.slice(0,Math.min(positions.length,Math.max(1,Math.min(4,(Number(p.age)||0)+1))));
}
function safeLock(w){
 if(disposed||state.busy||state.ended)return;
 const chars=Array.from(w.word),positions=state.safePositions,step=state.safeSolved,index=positions[step],correct=chars[index];
 const alternatives=/[а-яё]/i.test(correct)?'аоеиёу':/[a-z]/i.test(correct)?'aeiou':'1234567890';
 const keys=[correct,...Array.from(alternatives).filter(c=>c.toLowerCase()!==correct.toLowerCase()).slice(0,2)].sort(()=>Math.random()-.5);
 shell(`<div class="question-panel safe-panel"><div class="question-step">ЗАДАНИЕ ${state.index+1} ИЗ ${p.words.length} · ЗАМОК ${step+1} ИЗ ${positions.length}</div><div class="safe-locks">${positions.map((_,i)=>`<span class="${i<step?'unlocked':i===step?'current':''}">${i<step?'✓':'⌑'}</span>`).join('')}</div><h3>Восстанови буквенный код</h3><div class="safe-code" aria-label="Слово с пропущенными буквами">${chars.map((letter,i)=>`<span class="${i===index?'current':positions.indexOf(i)>=step&&positions.includes(i)?'hidden-letter':''}">${positions.includes(i)&&positions.indexOf(i)>=step?'?':esc(letter)}</span>`).join('')}</div><p class="safe-instruction">Какая буква откроет выделенный замок?</p><div class="safe-keys">${keys.map(key=>`<button class="game-answer" data-safe-key="${esc(key)}" aria-label="Буква ${esc(key)}">${esc(key)}</button>`).join('')}</div><div class="answer-feedback" aria-live="polite"></div></div>`);
 root.querySelectorAll('[data-safe-key]').forEach(button=>button.onclick=()=>{
  if(disposed||state.busy||state.ended||step!==state.safeSolved)return;
  if(button.dataset.safeKey!==correct){let wrong=[...chars];wrong[index]=button.dataset.safeKey;answer(wrong.join(''),w);return;}
  state.safeSolved++;
  if(state.safeSolved===positions.length){root.querySelector('.safe-locks').innerHTML=positions.map(()=>'<span class="unlocked">✓</span>').join('');root.querySelector('.safe-code').textContent=w.word;answer(w.word,w);}else{beep(true);safeLock(w);}
 });
}
function beep(ok){if(!p.sound)return;try{const a=new (window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);g.gain.value=(p.volume||50)/500;o.frequency.value=ok?660:220;o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close();}catch{}}
function answer(value,w){if(state.busy||state.ended)return;state.busy=true;let ok=value.trim().toLocaleLowerCase('ru')===w.word.trim().toLocaleLowerCase('ru');beep(ok);let f=root.querySelector('.answer-feedback');if(ok){state.score+=p.points;state.done.push(w.id);f.textContent='Верно! '+(w.explanation||'Отличная работа ✨');f.classList.add('correct');}else{state.mistakes++;if(p.lives)state.lives--;f.textContent='Правильно: '+w.word+(w.explanation?' · '+w.explanation:'');f.classList.add('incorrect');}root.querySelectorAll('.game-answer,.game-submit,[data-letter],[data-safe-key]').forEach(b=>b.disabled=true);setTimeout(()=>{if(disposed)return;if(p.lives&&state.lives<=0)return finish(false);state.index++;round();},ok?1000:1800);}
function finish(won){state.ended=true;clearInterval(interval);shell(`<div class="game-final"><div class="final-symbol">${won?'🏆':'🌱'}</div><div class="scene-eyebrow">${won?'ПРИКЛЮЧЕНИЕ ЗАВЕРШЕНО':'ВСЁ ПОЛУЧИТСЯ'}</div><h2>${esc(won?p.winText:p.loseText)}</h2><div class="final-stats"><span><b>${state.score}</b>баллов</span><span><b>${state.done.length}/${p.words.length}</b>верных ответов</span><span><b>${state.mistakes}</b>ошибок</span><span><b>${Math.round((Date.now()-startedAt)/1000)} с</b>время</span></div><button class="game-start">Играть ещё раз ↻</button></div>`);root.querySelector('.game-start').onclick=()=>{state={index:0,score:0,mistakes:0,lives:p.lives,done:[],started:false,ended:false,letters:[],selected:[],busy:false,time:p.timer};start();};}
intro();return{destroy(){disposed=true;clearInterval(interval);},start};
}
